let S;

function setup() {
	S = ~~(max(windowWidth, windowHeight) / ~~random(3, 13));
  createCanvas(S*~~(windowWidth/S), S*~~(windowHeight/S)); // (S = max(windowWidth, windowHeight)), S
	background(2, 2, 8);
	describe("grid of intersecting lines forming a grid with log distances");

  noFill();
  strokeWeight(1);
	// colorMode(HSB, 1);
  loop();
}

function draw() {
	blendMode(BLEND);
  // background("rgb(0, 0, 8)");
	background(2, 2, 8)
	// blendMode(ADD);

	// horiz
	stroke("cyan")
  for (let y = 0; y < height; y += S) {
		let pos = y;
		let target = y+S;
		for (let i = 0; i < 7; i++) {
			line(0, pos, width, pos);
			pos = lerp(pos, target, 0.3);
		}
	}
	stroke("purple")
	for (let x = 0; x < width; x += S) {
		var pos = x;
		var target = x+S;
		for (let i = 0; i < 7; i++) {
			line(pos, 0, pos, height);
			pos = lerp(pos, target, 0.3);
		}
	}

  // noLoop() removed for animation
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
